using System.Text.RegularExpressions;

namespace Crm.Api.Files;

/// <summary>Blob storage for attachments. Keys are generated by the server, never derived from user input.</summary>
public interface IFileStorage
{
    Task SaveAsync(string key, Stream content, CancellationToken ct);
    Task<Stream?> OpenReadAsync(string key, CancellationToken ct);
    Task DeleteAsync(string key, CancellationToken ct);
    Task DeleteTenantAsync(Guid tenantId, CancellationToken ct);
}

public static partial class StorageKeys
{
    [GeneratedRegex("^[0-9a-f]{32}/[0-9]{6}/[0-9a-f]{32}$")]
    private static partial Regex Pattern();

    public static string New(Guid tenantId, DateTime now) => $"{tenantId:N}/{now:yyyyMM}/{Guid.NewGuid():N}";

    public static string Validate(string key) =>
        Pattern().IsMatch(key) ? key : throw new ArgumentException("Invalid storage key.", nameof(key));
}

/// <summary>
/// Stores files on a local or mounted disk (<c>Storage:LocalPath</c>). Suitable for a single server or a shared volume;
/// cloud object storage can be added as another <see cref="IFileStorage"/> implementation.
/// </summary>
public sealed class LocalFileStorage : IFileStorage
{
    private readonly string _root;

    public LocalFileStorage(IConfiguration config, IHostEnvironment env)
    {
        var configured = config["Storage:LocalPath"];
        _root = Path.GetFullPath(string.IsNullOrWhiteSpace(configured) ? Path.Combine(env.ContentRootPath, "App_Data", "files") : configured);
    }

    private string PathFor(string key) => Path.Combine(_root, StorageKeys.Validate(key).Replace('/', Path.DirectorySeparatorChar));

    public async Task SaveAsync(string key, Stream content, CancellationToken ct)
    {
        var path = PathFor(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var temp = path + ".tmp";
        try
        {
            await using (var file = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true))
                await content.CopyToAsync(file, ct);
            File.Move(temp, path);
        }
        finally
        {
            if (File.Exists(temp)) File.Delete(temp);
        }
    }

    public Task<Stream?> OpenReadAsync(string key, CancellationToken ct)
    {
        var path = PathFor(key);
        return Task.FromResult<Stream?>(File.Exists(path)
            ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true)
            : null);
    }

    public Task DeleteAsync(string key, CancellationToken ct)
    {
        var path = PathFor(key);
        if (File.Exists(path)) File.Delete(path);
        return Task.CompletedTask;
    }

    public Task DeleteTenantAsync(Guid tenantId, CancellationToken ct)
    {
        var dir = Path.Combine(_root, tenantId.ToString("N"));
        if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true);
        return Task.CompletedTask;
    }
}
